set retStr = ""

try {
	set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
	set stat = deployCls.ValidateSvnRevision(comp, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), revNum )
	if $$$ISERR(stat)
	{
		 if $GET(%objlasterror) '= ""
    	{
        	set retStr =  $System.Status.GetErrorText(%objlasterror)
    	}
    	else
    	{
			set retStr = "Fail: " _ tSC
    	}
	}

} catch(err)
{
	set retStr = "Exception: Could not find files from SVN " _ err.Data
}
// Remove unprintable chars

return $ZSTRIP(retStr, "*C")


set retStr = ""
set sysEnv = $ZCVT($SYSTEM, "U")
if ( $FIND(sysEnv, "PRD") > 0)
{
	set env = "PROD"
}
elseif ( $FIND(sysEnv, "UAT") > 0)
{
	set env = "UAT"
}
elseif ( $FIND(sysEnv, "QA") > 0)
{
	set env = "QA"
}
else
{
	set env = "DEV"
}
try {
	set comp = $ZSTRIP(comp,"<>WC")
	set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
	set retStr = deployCls.DeployFile(comp, deployType , nmSp , $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), revNum, env, depCls,  depConf, changeCls)
	if (updateSettings = 1)
	{
		set crFl =  ##class(IHC.ITF.SrcCtrlPkg.CreateSettingFiles).%New()
		set stat = crFl.updateSettings(nmSp, comp, env, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), settingRev, .statStr)
		set retStr = retStr _ "; Update setting output: " _ statStr
	}

} catch(err)
{
	set retStr = "Exception: CallDeployService Could not deploy files " _ err.Data
}
return retStr


set retStr = ""
set sysEnv = $ZCVT($SYSTEM, "U")
if ( $FIND(sysEnv, "PRD") > 0)
