try {
	if (fName '= "")
	{
		set deployCls = ##class(IHC.ITF.SrcCtrlPkg.DeployFilesToNamespace).%New()
		set stat =  deployCls.DeployFiles(fName, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), env, .retStr)

		if $$$ISOK(stat)
		{
			set retStr = "<B>Status: </B>;; " _ retStr
			set retStr = $Replace(retStr, ";", "<br/>")
		}
		else
		{

			set retStr = "<B>Failed</B>; Details: " _ %objlasterror _ "; " _retStr
		}
	}
	else
	{
		set retStr = "Deploy filename is NULL"
	}

} catch(err)
{
	set retStr = "Exception: CallDeployFile Could not deploy files " _ err.Data
}
Do ..%SetValueById("lblAccess", retStr)

Quit


